import{_ as a,o as t,c as l,a2 as i}from"./chunks/framework.CDU0sSpB.js";const p=JSON.parse('{"title":"4.2 建立主动收件箱","description":"把建议集中到一个容易判断和处理的地方。","frontmatter":{"title":"4.2 建立主动收件箱","description":"把建议集中到一个容易判断和处理的地方。","outline":[2,3]},"headers":[],"relativePath":"delivery/stage-4/4-2.md","filePath":"delivery/stage-4/4-2.md","lastUpdated":null}'),r={name:"delivery/stage-4/4-2.md"};function o(n,e,s,d,_,c){return t(),l("div",null,[...e[0]||(e[0]=[i('<h1 id="_4-2-建立主动收件箱" tabindex="-1">4.2 建立主动收件箱 <a class="header-anchor" href="#_4-2-建立主动收件箱" aria-label="Permalink to &quot;4.2 建立主动收件箱&quot;">​</a></h1><h2 id="目标" tabindex="-1">目标 <a class="header-anchor" href="#目标" aria-label="Permalink to &quot;目标&quot;">​</a></h2><p>把主动建议集中到一个用户容易处理的地方，让用户一眼看出什么重要、为什么重要、需要自己做什么。</p><h2 id="怎么做" tabindex="-1">怎么做 <a class="header-anchor" href="#怎么做" aria-label="Permalink to &quot;怎么做&quot;">​</a></h2><ol><li>建立统一的主动收件箱，按重要性和时间分组，不把建议散落在各个页面。</li><li>每条内容显示来源、建议动作、预计影响、预计花费和是否需要审批。</li><li>提供接受、忽略、稍后提醒和转成任务四个动作，避免重复打扰。</li><li>支持安静时段、每日上限和批量处理，让用户能控制被打扰的程度。</li><li>用户忽略后不要换一种说法继续推送；同一事件只保留一条记录。</li><li>用真实建议检验：用户能快速判断，且不会因为数量过多而关闭通知。</li></ol>',5)])])}const u=a(r,[["render",o]]);export{p as __pageData,u as default};
